import { useState, useRef } from "react";
import StudentLayout from "./StudentLayout";

const ALL_SKILLS = [
  "React","Vue","Angular","Node.js","Express","Django","FastAPI",
  "Laravel","Python","Java","PHP","C++","SQL","PostgreSQL","MongoDB",
  "Docker","Git","Linux","Flutter","TypeScript","Redis","Kubernetes",
  "GraphQL","REST API","TensorFlow","Figma"
];
const WILAYAS = [
  "Alger","Oran","Constantine","Annaba","Béjaïa","Tizi Ouzou",
  "Blida","Sétif","Tlemcen","Batna","Bordj Bou Arréridj","Boumerdès","Tipaza","Médéa","Djelfa"
];


const GlobalStyles = () => (
  <style>{`
    @keyframes spin    { to{transform:rotate(360deg)} }
    @keyframes scale-in{ from{opacity:0;transform:scale(.92)} to{opacity:1;transform:scale(1)} }

    .anim-fade-up  { animation:fade-up .5s ease both; }
    .anim-scale-in { animation:scale-in .35s ease both; }
    .anim-d1 { animation-delay:.07s; }
    .anim-d2 { animation-delay:.14s; }

    .shimmer-btn {
      background:linear-gradient(90deg,#1A4A8A 0%,#2E7DF7 45%,#1A4A8A 100%);
      background-size:200% auto; animation:shimmer 3s linear infinite;
    }
    .shimmer-btn:hover { box-shadow:0 6px 20px rgba(46,125,247,.35); }

    .input-field {
      width:100%; padding:.7rem 1rem; border-radius:10px;
      border:1.5px solid #E2E8F0; font-family:'DM Sans',sans-serif;
      font-size:.875rem; color:#1C2B40; background:#F8FAFC; outline:none;
      transition:border-color .2s,box-shadow .2s,background .2s;
    }
    .input-field:focus { border-color:#2E7DF7; background:#fff; box-shadow:0 0 0 3px rgba(46,125,247,.1); }

    .card { background:#fff; border-radius:16px; border:1px solid #E8EDF5; }

    .badge { display:inline-flex; align-items:center; font-size:.7rem; font-weight:600; padding:.25rem .65rem; border-radius:100px; }
    .badge-blue  { background:#EBF2FF; color:#2563EB; }
    .badge-green { background:#ECFDF5; color:#059669; }
    .badge-slate { background:#F1F5F9; color:#475569; }

    .tab-btn {
      padding:.5rem 1rem; border-radius:8px; font-size:.82rem; font-weight:500;
      cursor:pointer; transition:all .18s; border:none; background:transparent;
      font-family:'DM Sans',sans-serif; display:flex; align-items:center; gap:.4rem;
    }
    .tab-btn.active   { background:#fff; color:#0B1F3A; box-shadow:0 1px 4px rgba(0,0,0,.1); }
    .tab-btn.inactive { color:#64748B; }

    .progress-bar-inner {
      height:100%; border-radius:100px;
      background:linear-gradient(90deg,#2E7DF7,#60A5FA); transition:width .6s ease;
    }

    .upload-zone {
      border:2px dashed #CBD5E1; border-radius:14px; padding:2rem; text-align:center; cursor:pointer; transition:all .22s; background:#F8FAFC;
    }
    .upload-zone:hover  { border-color:#2E7DF7; background:#EBF2FF; }
    .upload-zone.filled { border-color:#059669; border-style:solid; background:#ECFDF5; }
    .upload-zone.drag   { border-color:#2E7DF7; background:#EBF2FF; transform:scale(1.01); }
 ` }</style>
);

function calcCompletion(p) {
  let s = 0;
  if (p.firstName && p.lastName) s += 15;
  if (p.email)                   s += 10;
  if (p.phone)                   s += 5;
  if (p.university)              s += 10;
  if (p.wilaya)                  s += 5;
  if (p.bio)                     s += 15;
  if (p.skills.length >= 3)      s += 15;
  if (p.github)                  s += 15;
  if (p.digitalCV)               s += 10;
  return s;
}
const INIT = {
  firstName:"Amira", lastName:"Benali",
  email:"amira.benali@ifa.edu.dz", phone:"+213 555 123 456",
  university:"IFA — Institut de Formation en Algorithmique",
  department:"Informatique", level:"L3",
  wilaya:"Alger",
  github:"https://github.com/amira-benali",
  portfolio:"", linkedin:"",
  bio:"Passionate CS student at IFA with a strong interest in full-stack web development.",
  skills:["React","Node.js","Python","SQL","Git","Docker"],
  digitalCV: null,
  languages:[
    {lang:"Arabic",level:"Native"},{lang:"French",level:"Fluent"},{lang:"English",level:"Professional"}
  ],
  education:[
    {degree:"Licence — Informatique",school:"IFA",year:"2023 — Present"},
    {degree:"Baccalauréat — Sciences",school:"Lycée Bouâlem Hassaïne",year:"2022"},
  ],
};

function CVUpload({ value, onChange, editing }) {
  const ref = useRef();
  const [drag, setDrag] = useState(false);
  const [busy, setBusy] = useState(false);

  const process = (file) => {
    if (!file) return;
    if (file.type !== "application/pdf") { alert("PDF only."); return; }
    if (file.size > 5*1024*1024)         { alert("Max 5 MB."); return; }
    setBusy(true);
    setTimeout(() => {
      onChange({ name: file.name, size: (file.size/1024).toFixed(0)+" KB", url: URL.createObjectURL(file) });
      setBusy(false);
    }, 1100);
  };

  if (!editing) {
    return (
      <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-200">
        <div className="w-12 h-12 bg-red-50 border border-red-100 rounded-xl flex items-center justify-center text-2xl shrink-0">📄</div>
        <div className="flex-1 min-w-0">
          {value
            ? <><div className="font-semibold text-sm text-slate-800 truncate">{value.name}</div>
                <div className="text-xs text-slate-400 mt-0.5">{value.size} · PDF</div></>
            : <div className="text-sm text-slate-400 italic">No CV uploaded yet</div>
          }
        </div>
        {value && (
          <a href={value.url} target="_blank" rel="noreferrer" className="text-xs font-semibold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg">View →</a>
        )}
      </div>
    );
  }

  return (
    <div>
      <input ref={ref} type="file" accept=".pdf" className="hidden" onChange={e=>process(e.target.files[0])} />
      <div
        onClick={() => ref.current.click()}
        onDragOver={e=>{e.preventDefault();setDrag(true);}}
        onDragLeave={()=>setDrag(false)}
        onDrop={e=>{e.preventDefault();setDrag(false);process(e.dataTransfer.files[0]);}}
        className={`upload-zone ${value?"filled":""} ${drag?"drag":""}`}
      >
        {busy ? (
          <div className="flex flex-col items-center gap-2">
            <div className="w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"/>
            <p className="text-sm text-blue-600 font-medium">Uploading…</p>
          </div>
        ) : value ? (
          <div className="flex flex-col items-center gap-1.5">
            <div className="text-3xl">✅</div>
            <p className="font-semibold text-emerald-700 text-sm">{value.name}</p>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-2">
            <div className="text-3xl">📄</div>
            <p className="font-semibold text-slate-700 text-sm">Drop your CV here</p>
          </div>
        )}
      </div>
      {value && (
        <button type="button" onClick={()=>onChange(null)} className="mt-2 text-xs text-red-500 font-medium">✕ Remove CV</button>
      )}
    </div>
  );
}

export default function StudentProfile() {
  const [profile, setProfile] = useState(INIT);
  const [editing, setEditing] = useState(false);
  const [saved,   setSaved]   = useState(false);
  const [draft,   setDraft]   = useState(INIT);
  const [tab,     setTab]     = useState("info");
  const upd = (k,v) => setDraft(d=>({...d,[k]:v}));
  const toggleSkill = s => setDraft(d=>({
    ...d, skills: d.skills.includes(s)?d.skills.filter(x=>x!==s):[...d.skills,s]
  }));
  const startEdit = () => { setDraft({...profile}); setEditing(true); };
  const save = () => { setProfile({...draft}); setEditing(false); setSaved(true); setTimeout(()=>setSaved(false),3000); };

  const pct = editing ? calcCompletion(draft) : calcCompletion(profile);

  const TABS = [
    {id:"info",   label:"Personal info", icon:"👤"},
    {id:"cv",     label:"Manage CV",     icon:"📄"},
    {id:"skills", label:"Skills",        icon:"⚡"},
    {id:"preview",label:"CV Preview",    icon:"🔍"},
  ];

  const Field = ({label,k,placeholder,type="text"}) => (
    <div>
      <label className="block text-xs font-semibold text-slate-500 uppercase mb-1.5">{label}</label>
      {editing
        ? <input type={type} value={draft[k]} onChange={e=>upd(k,e.target.value)} placeholder={placeholder} className="input-field"/>
        : <p className="text-sm text-slate-700 font-medium py-2 px-3 bg-slate-50 rounded-lg">{profile[k]||"Not set"}</p>
      }
    </div>
  );

  return (
    <>
      <GlobalStyles/>
      <StudentLayout active="profile">
        <div className="p-5 md:p-8 max-w-4xl mx-auto">
          <div className="anim-fade-up flex items-start justify-between flex-wrap gap-3 mb-6">
            <div>
              <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl">My profile</h1>
            </div>
            <div className="flex gap-2 items-center">
              {saved && <span className="anim-scale-in text-xs text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-lg">✓ Saved!</span>}
              {!editing
                ? <button onClick={startEdit} className="shimmer-btn text-white text-sm font-semibold px-5 py-2.5 rounded-xl">Edit profile</button>
                : <button onClick={save} className="shimmer-btn text-white text-sm font-semibold px-5 py-2.5 rounded-xl">Save changes</button>
              }
            </div>
          </div>

          <div className="anim-fade-up anim-d1 card p-5 mb-5">
            <div className="flex flex-col md:flex-row gap-4 items-start">
              <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-blue-400 to-blue-700 flex items-center justify-center text-2xl font-bold text-white">
                {profile.firstName[0]}{profile.lastName[0]}
              </div>
              <div className="flex-1">
                <h2 className="font-syne font-extrabold text-slate-900 text-xl">{profile.firstName} {profile.lastName}</h2>
                <p className="text-slate-500 text-sm">{profile.level} · {profile.university}</p>
              </div>
              <div className="md:text-right">
                <div className="font-syne font-extrabold text-3xl text-blue-600">{pct}%</div>
                <div className="h-2 w-28 bg-slate-100 rounded-full overflow-hidden ml-auto">
                  <div className="progress-bar-inner" style={{width: `${pct}%`}}/>
                </div>
              </div>
            </div>
          </div>

          <div className="anim-fade-up anim-d2 flex flex-wrap gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-5">
            {TABS.map(t=>(
              <button key={t.id} onClick={()=>setTab(t.id)} className={`tab-btn ${tab===t.id?"active":"inactive"}`}>
                <span>{t.icon}</span><span>{t.label}</span>
              </button>
            ))}
          </div>

          {tab==="info" && (
            <div className="anim-fade-up space-y-4">
              <div className="card p-5">
                <div className="grid md:grid-cols-2 gap-4">
                  <Field label="First name" k="firstName" />
                  <Field label="Last name"  k="lastName"  />
                  <Field label="Email"      k="email"     type="email"/>
                  <Field label="Phone"      k="phone"     />
                </div>
              </div>
              <div className="card p-5">
                 <div className="grid md:grid-cols-2 gap-4">
                    <div className="md:col-span-2">
                      <label className="block text-xs font-semibold text-slate-500 uppercase mb-1.5">University</label>
                      {editing 
                        ? <input value={draft.university} onChange={e=>upd("university", e.target.value)} className="input-field"/>
                        : <p className="text-sm text-slate-700 font-medium py-2 px-3 bg-slate-50 rounded-lg">{profile.university}</p>
                      }
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 uppercase mb-1.5">Wilaya</label>
                      {editing 
                        ? <select value={draft.wilaya} onChange={e=>upd("wilaya", e.target.value)} className="input-field">
                            {WILAYAS.map(w=><option key={w} value={w}>{w}</option>)}
                          </select>
                        : <p className="text-sm text-slate-700 font-medium py-2 px-3 bg-slate-50 rounded-lg">{profile.wilaya}</p>
                      }
                    </div>
                 </div>
              </div>
            </div>
          )}

          {tab==="cv" && (
            <div className="anim-fade-up space-y-4">
              <div className="card p-5">
                <h3 className="font-syne font-bold text-slate-800 mb-4">Digital CV (PDF)</h3>
                <CVUpload
                  value={editing ? draft.digitalCV : profile.digitalCV}
                  onChange={v => upd("digitalCV", v)}
                  editing={editing}
                />
              </div>
            </div>
          )}

          {tab==="skills" && (
            <div className="anim-fade-up space-y-4">
              <div className="card p-5">
                <div className="flex flex-wrap gap-2">
                  {(editing ? draft : profile).skills.map(s=>(
                    <span key={s} className="text-sm px-3 py-1.5 rounded-full bg-blue-50 text-blue-700 font-medium border border-blue-200">{s}</span>
                  ))}
                  {editing && ALL_SKILLS.filter(s=>!draft.skills.includes(s)).map(s=>(
                    <button key={s} onClick={()=>toggleSkill(s)} className="text-sm px-3 py-1.5 rounded-full border border-slate-200 text-slate-500 hover:border-blue-300">
                      + {s}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {tab==="preview" && (
            <div className="anim-fade-up card p-8 bg-white">
              <h2 className="font-syne font-extrabold text-2xl border-b-2 border-slate-900 pb-4 mb-6">
                {profile.firstName} {profile.lastName}
              </h2>
              <div className="space-y-4">
                <div>
                  <h4 className="text-xs font-bold uppercase text-blue-600 mb-2">Education</h4>
                  <p className="text-sm">{profile.university} — {profile.level}</p>
                </div>
                <div>
                  <h4 className="text-xs font-bold uppercase text-blue-600 mb-2">Skills</h4>
                  <div className="flex flex-wrap gap-2">
                    {profile.skills.map(s=><span key={s} className="text-xs bg-slate-100 px-2 py-1 rounded">{s}</span>)}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </StudentLayout>
    </>
  );
}
